"""Build the human-readable review from the same contracts used by the server."""
import json,html,collections
from pathlib import Path
rows=json.loads(Path('src/routing/skillInputContracts.json').read_text())
esc=html.escape
labels={'explain':'Explain now','scoped':'Resolve subject / scope','personal':'Personal details for a conclusion'}
body=[]
for r in rows:
 body.append(f'''<tr data-mode="{r['mode']}"><td><strong>{esc(r['name'])}</strong><small>{r['id']}</small></td><td><span class="tag {r['mode']}">{labels[r['mode']]}</span></td><td>{esc(r['needed_for_specific_answer'])}<details><summary>See input and evidence rules</summary><p><b>Subject:</b> {esc(r['subject'])}</p><p><b>Optional:</b> {esc(r['optional_details'])}</p><p><b>Without new input:</b> {esc(r['without_new_input'])}</p><p><b>Evidence:</b> {esc(r['evidence_rule'])}</p><p><b>Missing-data handling:</b> {esc(r['missing_data_logic'])}</p></details></td><td>{esc(r['first_question'])}<small>Example only. Ask only if this detail is missing and changes the answer.</small></td></tr>''')
scenarios=[
 ('Explain a known skill','“What does critical thinking mean?”','Explain immediately with an everyday example and a useful practice activity. No age, location or qualification questionnaire.'),
 ('Explain a course unit','“Explain these units” after naming the course','Reuse the course. Explain what each unit develops, a practical task and relevance to the goal. Check the syllabus for actual content.'),
 ('Several possible courses','“What will it cost?” after comparing two courses','Ask which course, or offer to compare both. Do not silently select one.'),
 ('Personal fee estimate','Course and intake known, fee category unknown','Explain fee components first; ask domestic/international/unsure only if needed for the estimate. Funding eligibility may need a later, specific question.'),
 ('Details already supplied','User already gave course, location and fee category','Reuse them. Missing published prices need a source check, not repeat intake.'),
 ('Current source unavailable','User asks for exact fees, jobs or intake dates','Say which specifics remain unverified. Use a connected lookup if available; otherwise offer the official-source check. Do not invent a result.'),
 ('Personal readiness','“Am I ready for this job?” with no relevant experience given','Explain what readiness means, then ask for a relevant example. Do not label the user unskilled simply because evidence is missing.'),
 ('User unsure or declines','“I don’t know” / “I don’t want to share that”','Give general guidance or clearly labelled alternatives. Avoid repeating the same question or blocking the whole conversation.'),
 ('Location-dependent search','“Find employers nearby” with no location','Ask the user to enter a city or region. Do not infer it from timezone or the institution.'),
 ('Skill question answered','User submits the current skill’s question','Retain the selected skill and incorporate the answer. Do not restart intake. Free-text follow-ups still use ordinary conversation context.'),
 ('User changes direction','“Actually, show me a different career”','Drop the old skill continuation and let normal counselling handle the new request.'),
 ('Source versus personal data','Course curriculum gap versus my skill gap','Course gap: compare curriculum evidence to role requirements. Personal gap: also needs the user’s relevant capability evidence.'),
 ('No follow-up wanted','“Just explain it; no questions”','Give the useful general answer and state any limits without a compulsory question.'),
 ('A question is already visible','Gemini asks an essential clarification','Show one clear question and hide optional skill suggestions until no question is active.'),
]
scenario_html=''.join(f'<tr><td>{esc(a)}</td><td>{esc(b)}</td><td>{esc(c)}</td></tr>' for a,b,c in scenarios)
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Yuzee — Input review for all 103 skills</title><style>
*{box-sizing:border-box}body{margin:0;color:#243045;background:#fff;font:16px/1.6 system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:44px 28px 90px}h1{font-size:36px;line-height:1.2;max-width:900px;margin:12px 0 24px}h2{font-size:25px;margin-top:44px}p,li{max-width:1000px}small{display:block;color:#627087;font-size:13px;margin-top:8px}.eyebrow{color:#7446ba;font-weight:650;letter-spacing:.08em;text-transform:uppercase;font-size:13px}.lede{font-size:21px;max-width:1000px}table{border-collapse:collapse;width:100%;text-align:left}th,td{border-bottom:1px solid #dce1e9;padding:18px 12px;vertical-align:top}th{font-size:14px;color:#4f5c70;background:#f7f8fb}td:first-child{min-width:180px}td:nth-child(3){min-width:280px}summary{color:#6840aa;cursor:pointer;margin-top:14px}details p{font-size:14px}.tag{display:inline-block;font-size:13px;border-radius:5px;padding:3px 7px;background:#edf2f8;color:#344e71}.explain{background:#eaf6f1;color:#216649}.personal{background:#f3eefe;color:#68419c}.filters{display:flex;gap:16px;align-items:end;flex-wrap:wrap;margin:22px 0}label{font-size:14px;font-weight:600}input,select{display:block;font:inherit;padding:12px;border:1px solid #bac4d2;border-radius:6px;margin-top:6px;min-width:270px;max-width:100%}.table-scroll{overflow:auto}a{color:#6840aa}.note{border-left:3px solid #9c81c7;padding-left:18px}button{font:inherit;cursor:pointer;background:#fff;border:1px solid #c7bdde;border-radius:6px;padding:9px 15px;color:#603798}#count{color:#627087}@media(max-width:600px){main{padding:25px 16px}h1{font-size:29px}.lede{font-size:18px}}@media print{.filters,button{display:none}main{max-width:none;padding:0}details{display:block}tr{break-inside:avoid}th,td{font-size:11px;padding:8px}.table-scroll{overflow:visible}}
</style><main><div class="eyebrow">Yuzee · 103-skill input review · 17 September 2026</div><h1>Ask only for information that changes the answer.</h1><p class="lede">All 103 user-facing skills have been reviewed individually. A skill needing information does not mean the user needs to enter it again.</p><p><b>29 explain immediately</b> once the subject is known. <b>53 need a clear subject or research scope.</b> <b>21 need relevant personal or team details before a tailored conclusion.</b> These are default task types, not compulsory forms. Any skill can need clarification if the topic is missing; all can reuse known context.</p><h2>How the conversation should work</h2><ol><li><b>MiniLM proposes a relevant skill.</b> Its similarity score is not proof that inputs are complete.</li><li><b>The server supplies that skill’s approved input rules.</b> Internal IDs and source dependencies are not questions for the user.</li><li><b>Gemini checks the request and available context.</b> It explains what it can, asks one essential missing question only when needed, or identifies a source gap.</li><li><b>The existing chat displays the answer.</b> Use a simple question when required; no automatic full intake form. Keep optional recommendations hidden while that question is active.</li><li><b>Continue from the answer.</b> A valid answer to the selected skill’s current question retains that skill. Topic changes and stale question submissions do not.</li></ol><p class="note"><b>Implemented:</b> all 103 input contracts are attached to selected-skill requests and the explanation reviewer. The main master prompt and response schema remain intact. Structured question continuation preserves the selected skill. <b>Limit:</b> deciding which facts are present still depends on Gemini’s interpretation of available context. This is not a new deterministic profile extractor or a certification of 103 live model answers. The contract does not create a source connection.</p><h2>What the user should experience</h2><p>These are expected behaviours for testing, not recorded Gemini responses.</p><div class="table-scroll"><table><thead><tr><th>Scenario</th><th>User situation</th><th>Expected handling</th></tr></thead><tbody>SCENARIOS</tbody></table></div><h2>Every skill, reviewed individually</h2><p>“Explain now” assumes the subject is known. Example questions are fallbacks, never automatic scripts. If the listed answer already exists in the conversation, skip the question.</p><div class="filters"><label>Find a skill<input id="search" type="search" placeholder="Fees, proficiency, COURSE_011…"></label><label>Show<select id="mode"><option value="">All 103 skills</option><option value="explain">29 — Explain now</option><option value="scoped">53 — Subject / scope</option><option value="personal">21 — Personal conclusion</option></select></label><button id="expand">Show all details</button><span id="count" role="status">103 skills shown</span></div><div class="table-scroll"><table id="skills"><thead><tr><th>Skill</th><th>Default handling</th><th>What actually matters</th><th>One possible question</th></tr></thead><tbody>ROWS</tbody></table></div><h2>Verification and remaining checks</h2><p>Automated checks cover catalogue completeness, all 103 request contracts, source-versus-user distinctions, valid skill continuation and rejection of stale, invalid, stopped, safety or changed-topic answers. The application build is checked separately. Live answer quality across all 103 skills still requires provider-backed conversation evaluation.</p><p>Before production approval, test each skill with sufficient context, a missing essential detail, unavailable evidence, a correction and an unsure answer. Confirm factual sources separately from presentation quality.</p></main><script>const rows=[...document.querySelectorAll('#skills tbody tr')];const search=document.querySelector('#search'),mode=document.querySelector('#mode');function filter(){const q=search.value.toLowerCase().trim();let n=0;rows.forEach(r=>{r.hidden=!!((mode.value&&r.dataset.mode!==mode.value)||!r.textContent.toLowerCase().includes(q));if(!r.hidden)n++});document.querySelector('#count').textContent=n+' skills shown'}search.addEventListener('input',filter);mode.addEventListener('change',filter);document.querySelector('#expand').onclick=e=>{const open=e.target.textContent==='Show all details';document.querySelectorAll('details').forEach(d=>d.open=open);e.target.textContent=open?'Hide all details':'Show all details'};</script></html>'''
Path('output/html/Yuzee-103-Skill-Input-Review.html').write_text(page.replace('SCENARIOS',scenario_html).replace('ROWS',''.join(body)))
print('Built 103-skill input report')
